<?php declare(strict_types=1);require __DIR__.'/_auth.php';require_get();$vendor=api_vendor();$s=db()->prepare('SELECT COUNT(*) total,COALESCE(SUM(redeemed_at>=CURDATE()),0) today FROM gift_redemptions WHERE vendor_id=?');$s->execute([$vendor['vendor_id']]);$stats=$s->fetch();$r=db()->prepare('SELECT gr.redemption_id,g.name gift,u.name user_name,gr.redeemed_at FROM gift_redemptions gr JOIN gifts g ON g.id=gr.gift_id JOIN users u ON u.id=gr.user_id WHERE gr.vendor_id=? ORDER BY gr.id DESC LIMIT 25');$r->execute([$vendor['vendor_id']]);json_response(true,'Vendor dashboard',['stats'=>$stats,'recent'=>$r->fetchAll()]);
